L550:                     "[features].web_search_request"
L551:                 }
L552:                 "features.web_search_cached" | "web_search_cached" => {
L553:                     "[features].web_search_cached"
L554:                 }
L555:                 _ => alias,
L556:             };
L557:             let summary =
L558:                 format!("`{label}` is deprecated because web search is enabled by default.");
L559:             (summary, Some(web_search_details().to_string()))
L560:         }
L561:         Feature::UseLegacyLandlock => {
L562:             let label = match alias {
L563:                 "features.use_legacy_landlock" | "use_legacy_landlock" => {
L564:                     "[features].use_legacy_landlock"
L565:                 }
L566:                 _ => alias,
L567:             };
L568:             let summary = format!("`{label}` is deprecated and will be removed soon.");
L569:             let details =
L570:                 "Remove this setting to stop opting into the legacy Linux sandbox behavior."
L571:                     .to_string();
L572:             (summary, Some(details))
L573:         }
L574:         _ => {
L575:             let label = if alias.contains('.') || alias.starts_with('[') {
L576:                 alias.to_string()
L577:             } else {
L578:                 format!("[features].{alias}")
L579:             };
L580:             let summary = format!("`{label}` is deprecated. Use `[features].{canonical}` instead.");
L581:             let details = if alias == canonical {
L582:                 None
L583:             } else {
L584:                 Some(format!(
L585:                     "Enable it with `--enable {canonical}` or `[features].{canonical}` in config.toml. See https://developers.openai.com/codex/config-basic#feature-flags for details."
